/**
 * 禁飞区审查业务的 H2 数据库测试（MODE=MySQL）。
 * 覆盖主流程、失败分支、版本失效（STALE）、幂等边界与真实并发互斥。
 */
@SpringBootTest
class AirspaceReviewServiceH2Test {

    @Autowired
    private AirspaceReviewServiceAccess service;
    @Autowired
