        ApiException stale = assertThrows(ApiException.class, () -> service.bean.review(
                new ReviewRequest("rp", 1, 0L, "req-" + rid("review"))));
        assertEquals(HttpStatus.CONFLICT, stale.status());
        // 新版本可审核
