    // ============================ STALE 语义 ============================

    @Test
    void currentReviewBecomesStaleAfterZoneChangeAndRouteReplace() {
        service.bean.createRoute(
                new RouteCreateRequest("st", pts(0, 10, 100, 10), "req-" + rid("route")));
        MutationResponse rev = service.bean.review(
                new ReviewRequest("st", 1, 0L, "req-" + rid("review")));
        ReviewResultDto dto = dataOf(rev);
        assertEquals("CLEAR", dto.conclusion());

        // 刚完成：当前结论可用
        ReviewResultDto current1 = service.bean.getCurrentReview("st");
        assertEquals("CLEAR", current1.conclusion());
        assertTrue(current1.current());

        // 空域变化：当前结论必须 STALE，旧 CLEAR 不能当成当前通过
        service.bean.createZone(zoneReq("nz", -90, -90, -80, -80));
        ReviewResultDto stale1 = service.bean.getCurrentReview("st");
        assertEquals("STALE", stale1.conclusion());
        assertFalse(stale1.current());
        // 历史结论不变
        assertEquals("CLEAR", service.bean.getReview(dto.reviewId()).conclusion());

        // 用新空域版本重新审核 → CLEAR，恢复可用
        MutationResponse rev2 = service.bean.review(
                new ReviewRequest("st", 1, 1L, "req-" + rid("review")));
        assertTrue(dataOf(rev2).current());
        assertEquals("CLEAR", service.bean.getCurrentReview("st").conclusion());

        // 航线替换后再次 STALE
        service.bean.replaceRoute(new RouteReplaceRequest(
                "st", 1, pts(0, 10, 100, 10), "req-" + rid("replace")));
        assertEquals("STALE", service.bean.getCurrentReview("st").conclusion());

        // 无审核记录查询 404
        ApiException ex = assertThrows(ApiException.class,
                () -> service.bean.getCurrentReview("never-reviewed"));
        assertEquals(HttpStatus.NOT_FOUND, ex.status());
    }

    @Test
    void blockedCurrentGoesStaleAndHistoricalBlockedStaysBlocked() {
