        service.bean.revokeZone(new ZoneRevokeRequest("bz", "req-" + rid("revoke")));
        // 撤销后旧 BLOCKED 对当前查询同样失效
        assertEquals("STALE", service.bean.getCurrentReview("bs").conclusion());
        assertEquals("BLOCKED", service.bean.getReview(blocked.reviewId()).conclusion());
