/**
 * 在当前事务内对全局版本行加写锁并读取版本。
 * 与 {@link #incrementGlobalVersion()} 的行更新互斥：审核事务持有此锁期间，
 * 任何禁飞区创建/撤销事务都无法提交，从而保证审核读到的版本号与全部禁飞区
 * 来自同一个已提交状态，杜绝“携带新版本、使用旧区域”的结论。
 */
public long getGlobalVersionForUpdate() {
    Long version = jdbc.queryForObject(
            "SELECT global_version FROM airspace_meta WHERE id = 1 FOR UPDATE", Long.class);
    return version == null ? 0L : version;
}

