/**
 * 在当前事务内对全局版本行加写锁并读取版本。
 *
 * <p>使用“值不变的 UPDATE”而非 SELECT ... FOR UPDATE 取行级排他锁：
 * 该写法在 H2（MVStore）与 MySQL InnoDB 下都确定地持有 X 锁至事务提交，
 * 与 {@link #incrementGlobalVersion()} 的行更新互斥。审核事务持有此锁期间，
 * 任何禁飞区创建/撤销事务都无法提交，从而保证审核读到的版本号与全部禁飞区
 * 来自同一个已提交状态，杜绝“携带新版本、使用旧区域”的结论。</p>
 */
public long getGlobalVersionForUpdate() {
    jdbc.update("UPDATE airspace_meta SET global_version = global_version WHERE id = 1");
    return getGlobalVersion();
}

