                    return ps.executeUpdate();
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });
            // 500ms 内不应完成（应被 c1 的行锁阻塞）
            boolean doneEarly;
            try {
                f2.get(500, TimeUnit.MILLISECONDS);
