package com.example.starter;

import com.example.starter.api.ApiException;
import com.example.starter.api.dto.MutationResponse;
import com.example.starter.api.dto.ReviewRequest;
import com.example.starter.api.dto.ReviewResultDto;
import com.example.starter.api.dto.RouteCreateRequest;
import com.example.starter.api.dto.RoutePointDto;
import com.example.starter.api.dto.ZoneCreateRequest;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

/**
 * 临时诊断：贴近业务复现并发，打印冲突时状态。
 */
@SpringBootTest
class H2ServiceRaceProbeTest {

    @Autowired
    private com.example.starter.service.AirspaceReviewService service;
    @Autowired
    private JdbcTemplate jdbc;
    @Autowired
    private ObjectMapper objectMapper;

    @Test
    void probeServiceRace() throws Exception {
        int blockedWithOldVersion = 0;
        int clear = 0;
        int conflict = 0;
        ExecutorService pool = Executors.newFixedThreadPool(4);
        try {
            for (int i = 0; i < 30; i++) {
                jdbc.update("DELETE FROM review");
                jdbc.update("DELETE FROM request_dedup");
                jdbc.update("DELETE FROM route_point");
                jdbc.update("DELETE FROM route");
                jdbc.update("DELETE FROM no_fly_zone");
                jdbc.update("UPDATE airspace_meta SET global_version = 0 WHERE id = 1");
                jdbc.update("UPDATE coord_lock SET touched = 0 WHERE id = 1");

                String routeId = "p" + i;
                String zoneId = "zp" + i;
                service.createRoute(new RouteCreateRequest(routeId,
                        List.of(new RoutePointDto(0, 10), new RoutePointDto(100, 10)),
                        "preq-route-" + i));

                CyclicBarrier barrier = new CyclicBarrier(2);
                Future<Object> rf = pool.submit(() -> {
                    barrier.await(5, TimeUnit.SECONDS);
                    try {
                        return service.review(new ReviewRequest(routeId, 1, 0L, "preq-rv-" + i));
                    } catch (ApiException e) {
                        return e;
                    }
                });
                Future<Object> zf = pool.submit(() -> {
                    barrier.await(5, TimeUnit.SECONDS);
                    try {
                        return service.createZone(new ZoneCreateRequest(
                                zoneId, 40, 5, 60, 15, "preq-zone-" + i));
                    } catch (ApiException e) {
                        return e;
                    }
                });
                Object rr = rf.get(15, TimeUnit.SECONDS);
                Object zr = zf.get(15, TimeUnit.SECONDS);
                if (rr instanceof MutationResponse mr) {
                    ReviewResultDto dto = objectMapper.convertValue(mr.data(), ReviewResultDto.class);
                    if ("BLOCKED".equals(dto.conclusion()) && dto.airspaceVersion() == 0L) {
                        blockedWithOldVersion++;
