package com.example.starter.config;

import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 初始化全局空域版本单行数据（初始版本 0）。
 * 建表由 schema.sql 完成；这里仅保证元数据行存在，重复启动幂等。
 */
@Configuration
public class DataInitializer {

    @Bean
    @Order(0)
    ApplicationRunner initAirspaceMeta(JdbcTemplate jdbc) {
        // H2 内存库随 JVM 创建，启动时表为空，插入初始版本行（版本 0）与协调锁行
        return args -> {
            jdbc.update("INSERT INTO airspace_meta (id, global_version) VALUES (1, 0)");
            jdbc.update("INSERT INTO coord_lock (id, touched) VALUES (1, 0)");
        };
    }
}

