/**
 * 计算请求参数的规范化哈希（SHA-256）。
 * 对象字段按键名字典序递归排序，列表保持顺序，使相同语义参数产生相同哈希。
 */
private String canonicalHash(Object request) {
    try {
        JsonNode node = objectMapper.valueToTree(request);
        sortNode(node);
        String canonical = objectMapper.writeValueAsString(node);
